// OutBound's three soft chimes (round 197), made by design/chimes-synth.py, AAC in M4A files, as data URIs.
// Made from design/sounds/<name>.wav with:
//   ffmpeg -i design/sounds/<name>.wav -c:a aac -b:a 96k -ac 1 -movflags +faststart assets/sounds/<name>.m4a
// then base64. iOS writes each to a temp file named .m4a, so it never depends on an asset file name (round 183).

export const ANSWERED_DATA_URI =
  'data:audio/mp4;base64,';

export const SENT_DATA_URI =
  'data:audio/mp4;base64,';

export const LEAVE_DATA_URI =
  'data:audio/mp4;base64,';
